import fs from 'node:fs/promises'
import {dir,db,asset,send,reviewed,task} from './reply-runtime-20261007.mjs'
const s=JSON.parse(await fs.readFile(dir+'/reply-refresh.json','utf8')),plans=[]
const get=n=>{const t=s.threads.find(t=>t.contact.name===n);if(!t)throw Error('Missing '+n);return t}
async function add(name,body,card=false,extra={}){const t=get(name),c=t.contact;plans.push({id:c.id,name,phone:c.phone,city:c.city,latest:t.touches.at(-1).id,from:'+14374650584',body,...(card?{media_urls:[await asset(c.city)]}:{}),...extra})}
const stop=get('LISA REIS');await db('market_contacts',{id:'eq.'+stop.contact.id},'PATCH',{do_not_contact:true,sequence_paused:true,sequence_paused_reason:'recipient_opt_out',decision:'opted_out',next_follow_up:null,cross_channel_suppressed_at:new Date().toISOString(),cross_channel_suppression_reason:'Recipient explicitly texted Stop October 7.'});await db('sequence_jobs',{contact_id:'eq.'+stop.contact.id,status:'eq.pending'},'PATCH',{status:'cancelled',error:'Recipient opted out'});await reviewed(stop.touches.at(-1).id,'Stop honoured: DNC and cross-channel suppression, pending jobs cancelled. No outbound reply.')
