const nick=get('NICK MACLENNAN');await add('NICK MACLENNAN',`Hi Nick,\n\nThanks for getting back to me. Here's our Whitby digital card to save or forward when a client needs moving help:\n${await asset('Whitby')}\n\nWe serve Whitby and the wider GTA. Clients can call or text 437-782-3004 for a moving quote. ${price}\n\nWebsite: https://starmovers.ca\n\nLooking forward to working together,\nJohn Owolabi\nSaturn Star Movers`,false,{channel:'email',email:'nick@teamfarr.ca',subject:'Your Saturn Star Movers card - Whitby',note:'Requested email/card sent to recipient-supplied address via SES.'})
await add('Julie DiLiberto-Kirkelos',`Hi Julie,\n\nIt was good speaking with you today. Thanks for considering us for your client's move from the apartment on Queenston Road in Stoney Creek.\n\nYou mentioned Friday, October 30 may be needed because the current movers can only do October 31, and that you expect to confirm tomorrow whether the date can change. Please send the confirmed moving date when you have it, along with the full pickup and destination addresses, a list or photos of the items, floors/elevator or stairs at each end, and any loading or parking restrictions.\n\nWith those details we can prepare the flat estimate we discussed and confirm the crew and timing. This email is a follow-up to collect the information for the quote; it is not a confirmed price or booking.\n\nHere's our Hamilton digital card to keep handy:\n${await asset('Hamilton')}\n\nYou can reply here or reach me on 437-465-0584, the number I texted from. Our website is https://starmovers.ca.\n\nThank you,\nJohn Owolabi\nSaturn Star Movers`,false,{channel:'email',email:'jkirkelo@gmail.com',subject:'Following our call: your client’s October 30 move',note:'Reviewed recorded owner call. Emailed requested follow-up and scope needed for flat estimate; no invented amount or booking confirmation.'})
